#!/usr/bin/env python3
"""Emit a C file holding one binary blob as a const array for a ROM bank.

Usage: python3 tools/bin2c_bank.py IN.bin SYMBOL OUT.c

The array is the only object in the file, so compiling it with
`sdcc --constseg BANKn` places it at the start of bank n. Read it at its
symbol address after SMS_mapROMBank(n).
"""
import sys


def main(argv):
    src, symbol, dst = argv[1], argv[2], argv[3]
    data = open(src, "rb").read()
    lines = [
        "/* Generated by tools/bin2c_bank.py from %s. Do not edit. */" % src,
        "const unsigned char %s[%d] = {" % (symbol, len(data)),
    ]
    for i in range(0, len(data), 16):
        chunk = data[i:i + 16]
        lines.append("    " + ",".join("0x%02x" % b for b in chunk) + ",")
    lines.append("};")
    with open(dst, "w") as fh:
        fh.write("\n".join(lines) + "\n")
    print(f"{dst}: {symbol}[{len(data)}]")
    return 0


if __name__ == "__main__":
    if len(sys.argv) != 4:
        sys.exit(__doc__)
    sys.exit(main(sys.argv))
